from __future__ import annotations

import os
import pathlib
import time
from abc import ABCMeta
from contextlib import contextmanager
from typing import Optional, Union

import attr
from moler.config import load_config, loaded_config  # type: ignore[import-untyped]
from moler.device import DeviceFactory  # type: ignore[import-untyped]
from taf.config.testline.ue import CUS as CusTaf  # type: ignore[import-untyped]
from ute_testline_configuration.ute_config import CUS as CusUte  # type: ignore[import-untyped]

from taf.ul.ue.sim.env_setup.devices.simulator import Simulator
from taf.ul.ue.sim.env_setup.utils.dict_types import SimulatorDictType
from taf.ul.ue.sim.env_setup.utils.enums import DevicesNames
from taf.ul.ue.sim.env_setup.utils.shell_utils import execute_remote_sudo_command, upload_to_remote


@attr.s(cmp=False, hash=True)
class RtgCusGenericInterface(Simulator, metaclass=ABCMeta):
    idx = attr.ib(type=int)
    remote_host = attr.ib(type=str)
    output_directory_path = attr.ib(type=str)
    configuration = attr.ib(type=Union[CusTaf, CusUte])
    config_type = attr.ib(type="str")
    name = attr.ib(type=DevicesNames)
    _config = attr.ib(
        type=SimulatorDictType,
        init=False,
        hash=False,
    )
    connected_bts_id = attr.ib(default=1, type=int, init=False)

    def _remove_moler_dev(self):
        DeviceFactory.remove_device(self.name.upper())

    def _get_lmp_ip_for_ute(self) -> str:
        return f"192.168.200.{self.idx}"

    def _get_lmp_ip_for_taf(self) -> str:
        return self.configuration.l1.common_units[0].lmp_connection.addr

    def _get_lmp_password(self) -> str:
        return self.configuration.l1.common_units[0].lmp_connection.password

    def set_config(self, config: SimulatorDictType) -> None:
        self._config = config

    def _configure(self, warning_lookup: bool, skip_restart: bool, is_combo: bool = False) -> None:
        self._log_device_version()
        if not self._is_any_config_file_provided():
            self.logger.debug("No config for CUS/RTG provided. Not going to configure anything here")
            return
        if self._config.get("db"):
            self._set_ue_db()
        self._update_config(warning_lookup, skip_restart, is_combo)

    def _update_config(self, warning_lookup: bool, skip_restart: bool, is_combo: bool) -> None:
        if is_combo:
            self._reset_executor_service_as_a_workaround()
        with self._get_executor(state=self.name.upper()) as executor:
            self._set_config_file_in_executor(executor, warning_lookup, is_combo)
            if not skip_restart:
                time.sleep(10)
                self._apply_config_remotely(executor)
                with self._get_remote_host_ssh() as ssh_connection:
                    self._wait_until_host_is_unavailable(ssh_connection, 30)
            else:
                self.logger.info("Skip simulator reset detected. Reset & remote config will not be performed")
        self._remove_device()

    def ensure_sibs_are_received(self, timeout):
        with self._get_executor("CUS") as executor:
            start_time = time.time()
            exc = None
            while (time.time() - start_time) < timeout:
                try:
                    cm_connect = executor.get_cmd("cm_connect", cmd_params={})
                    self.logger.debug("Executing CM CONNECT on executor")
                    ret = cm_connect(timeout=10)
                    self.logger.debug("Executing CM CONNECT on executor - SUCCESS")
                    return ret
                except Exception as err:
                    self.logger.debug(err)
                    time.sleep(2)
                    exc = err
            else:
                raise CmConnectFailure(exc)

    def _is_any_config_file_provided(self):
        try:
            return self._config and "file" in self._config
        except Exception as err:
            self.logger.warning(err)
            return False

    def _get_moler_config(self):
        moler_configuration = {
            "LOGGER": {
                "PATH": f"{self.output_directory_path}/moler_logs",
                "RAW_LOG": True,
                "DEBUG_LEVEL": "DEBUG",
            },
            "DEVICES": {
                f"{self.name.upper()}": {
                    "DEVICE_CLASS": f"ta_moler.device.{self.name.lower()}.{self.name.upper()}",
                    "CONNECTION_HOPS": {
                        "UNIX_LOCAL": {  # from state
                            "WS": {  # to state
                                "execute_command": "ssh",  # via command
                                "command_params": {  # with params
                                    "expected_prompt": "ute@.*",
                                    "host": self.remote_host if self.remote_host else "localhost",
                                    "login": "ute",
                                    "password": "ute",
                                },
                            }
                        },
                        "WS": {
                            f"{self.name.upper()}": {
                                "execute_command": "telnet",
                                "command_params": {"expected_prompt": (r"^(\s*(\d{2}\.\d{2}:\d{2}:\d{2}\.\d+\|\s*))?" + f"{self.name.upper()}>")},
                            },
                            "UNIX_LOCAL": {
                                "execute_command": "exit",
                                "command_params": {
                                    "expected_prompt": "moler_bash",
                                    # 'expected_prompt': '.*',
                                    "timeout": 2,
                                },
                            },
                        },
                        f"{self.name.upper()}": {
                            "WS": {
                                "execute_command": "exit_telnet",
                                "command_params": {
                                    "expected_prompt": "ute@.*",
                                },
                            }
                        },
                        "WS_ROOT": {
                            "WS": {
                                "execute_command": "exit",
                                "command_params": {"expected_prompt": "ute@.*"},
                            }
                        },
                    },
                }
            },
        }
        self.logger.debug(moler_configuration)
        return moler_configuration

    def _set_ue_db(self):
        _from, _to = pathlib.Path(self._config["db"]), pathlib.Path("/opt", self.name.name.lower(), "etc")
        self.logger.debug(f"Changing rights of {_from} to 0775")
        _from.chmod(0o775)
        self.logger.debug(f"Removing old UE DB file in {_to}")
        execute_remote_sudo_command(self.remote_host, "rm -rf {}".format((_to / "ue.db").as_posix()), self.logger)
        execute_remote_sudo_command(self.remote_host, "rm -rf {}".format((_to / "UEDB.db").as_posix()), self.logger)
        self.logger.debug(f"Copying {_from} to {self.remote_host} {_to}")
        upload_to_remote(self.remote_host, _from.as_posix(), (_to / "ue.db").as_posix(), self.logger)

    def list_files(self, startpath):
        for root, dirs, files in os.walk(startpath):
            level = root.replace(startpath, "").count(os.sep)
            indent = " " * 4 * level
            self.logger.debug(f"{indent}{os.path.basename(root)}/")
            subindent = " " * 4 * (level + 1)
            for f in files:
                self.logger.debug(f"{subindent}{f}")

    def _set_config_file_in_executor(self, executor, warning_lookup: bool, is_combo: bool = False):
        config_update_params = {
            "path": self._config["file"],
            "fail_on_warning": warning_lookup,
        }
        self._execute_cmd(executor, "config_update", cmd_params=config_update_params, timeout=90)
        if is_combo:
            self._set_config_file_in_executor_for_combo(executor, config_update_params)

    def _set_config_file_in_executor_for_combo(self, executor, config_update_params):
        if self._wait_for_wts_endc_setup(executor):
            self._execute_cmd(executor, "config_update", cmd_params=config_update_params, timeout=90)
        else:
            self.logger.warning("WTS has not configured 5G cells")

    def _wait_for_wts_endc_setup(self, executor, wts_endc_setup_timeout=90):
        start_time = time.time()
        while time.time() - start_time < wts_endc_setup_timeout:
            ret = self._execute_cmd(executor, "display_endc_wts")
            self.logger.debug(f"display_endc_wts: {ret}")
            if isinstance(ret, list) and len(ret) > 0:
                return True
            time.sleep(10)
        return False

    @contextmanager
    def _get_executor(self, state=None):
        dev_name = self.name.upper()
        try:
            if "NOT_LOADED_YET" in loaded_config:
                config = self._get_moler_config()
                load_config(config=config)
            executor = DeviceFactory.get_device(dev_name)
            if state:
                executor.goto_state(state)
            yield executor
            executor.remove()
        except Exception as err:
            self.logger.error(err, exc_info=True)
            raise

    def _apply_config_remotely(self, executor):
        self._execute_cmd(executor, "config_remote_update", timeout=300)

    def _log_device_version(self):
        with self._get_executor(self.name.upper()) as executor:
            version = self._execute_cmd(executor, "version")
            self.logger.debug(version)

    def _remove_device(self):
        dev_name = self.name.upper()
        try:
            DeviceFactory.remove_device(dev_name)
        except KeyError as err:
            if f"Device named '{self.name.upper()}' was not defined inside configuration" in str(err):
                pass

    def reset(self):
        with self._get_executor(self.name.upper()) as executor:
            try:
                self._execute_cmd(executor, "config_remote_restart", cmd_params={"target": "ctrl"})
            except Exception as err:
                self.logger.debug(err, exc_info=True)
                super().reset()

    def _execute_cmd(
        self,
        device: DeviceFactory.get_device,
        cmd_name: str,
        cmd_params: Optional[dict] = None,
        timeout: Optional[int] = 90,
    ) -> str:
        self.logger.debug(f"Executing cmd: '{cmd_name}' with params: '{cmd_params}'")
        cmd = device.get_cmd(cmd_name, cmd_params=cmd_params)
        cmd(timeout=timeout)
        self.logger.debug(f"Command '{cmd_name}' finished with success")
        return cmd.result()

    def _reset_executor_service_as_a_workaround(self):
        with self._get_executor("WS") as ws:
            service_restart = ws.get_cmd("service", {"options": "cus-executor restart"})
            sudo_service_restart = ws.get_cmd("sudo", {"cmd_object": service_restart})
            sudo_service_restart()
            self.logger.info("'cus-executor' service restarted. Waiting for executor to be back.")
            ws.goto_state("CUS", timeout=3, rerun=10)
            self.logger.info("Executor is back. Can continue.")


class CmConnectFailure(Exception):
    pass
